describe("custom validator", () => {
  it("Valid JSON", async () => {
    const res = await t.fetch("/custom", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ field: "value" }),
    });
    expect(await res.json()).toEqual({
      field: "value",
      default: "default",
    });
    expect(res.status).toEqual(200);
  });

  it("Validate x-www-form-urlencoded", async () => {
    const res = await t.fetch("/custom", {
      method: "POST",
      headers: { "Content-Type": "application/x-www-form-urlencoded" },
      body: "field=value",
    });
    expect(await res.json()).toEqual({
      field: "value",
      default: "default",
    });
    expect(res.status).toEqual(200);
  });

  it("Invalid JSON", async () => {
    const res = await t.fetch("/custom", {
      method: "POST",
      body: JSON.stringify({ invalid: true }),
    });
    expect(await res.text()).include("Invalid key");
    expect(res.status).toEqual(400);
  });
});

describe("zod validator", () => {
  it("Valid multipart form data", async () => {
    t.app.post("/form-data", (event) =>
      readValidatedBody(event, zodValidate, { type: "formData" }),
    );

    const formData = new FormData();
    formData.set("field", "value");
    const res = await t.fetch("/form-data", {
      method: "POST",
      body: formData,
    });

    expect(await res.json()).toEqual({
      field: "value",
      default: "default",
    });
  });

  it("Valid", async () => {
    const res = await t.fetch("/zod", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ field: "value" }),
    });
    expect(await res.json()).toEqual({
      field: "value",
      default: "default",
    });
    expect(res.status).toEqual(200);
  });

